import{_ as s,o as t,c as a,a2 as o}from"./chunks/framework.CNDaxUod.js";const k=JSON.parse('{"title":"Claude Code and MCP","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mcp.md","filePath":"guide/mcp.md"}'),i={name:"guide/mcp.md"};function n(d,e,r,h,l,c){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="claude-code-and-mcp" tabindex="-1">Claude Code and MCP <a class="header-anchor" href="#claude-code-and-mcp" aria-label="Permalink to &quot;Claude Code and MCP&quot;">​</a></h1><p>AsyncUp has no AI of its own. Instead it speaks the <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a> at <code>/mcp</code>, so an assistant your team already uses can read standups and, with the right scopes, act as a person: answer today&#39;s standup, chase a blocker, mark a day off or nudge the team.</p><p>It is built and tested for <strong>Claude Code</strong>. Cursor, VS Code and any other client that can send a bearer token header work the same way. Claude.ai and ChatGPT connectors need OAuth sign-in, which AsyncUp does not offer yet.</p><h2 id="_1-switch-it-on" tabindex="-1">1. Switch it on <a class="header-anchor" href="#_1-switch-it-on" aria-label="Permalink to &quot;1. Switch it on&quot;">​</a></h2><p>An admin turns the server on under <strong>Settings › MCP server</strong> and picks the default scopes new tokens get (read-only unless changed). While it is off, <code>/mcp</code> answers <code>503 mcp_disabled</code>.</p><h2 id="_2-create-a-token" tabindex="-1">2. Create a token <a class="header-anchor" href="#_2-create-a-token" aria-label="Permalink to &quot;2. Create a token&quot;">​</a></h2><p>On the same page, <strong>New token</strong>:</p><ul><li>A <strong>personal</strong> token acts as you. It sees what you see in the web app and writes as you. Anyone signed in can make one.</li><li>A <strong>service</strong> token needs the <code>tokens.manage</code> permission. It is read-only and sees the whole workspace. Use it for reports and dashboards, not for acting as a person.</li></ul><p>Pick only the scopes the assistant needs:</p><table tabindex="0"><thead><tr><th>Scope</th><th>Tools</th></tr></thead><tbody><tr><td><code>read</code></td><td><code>get_me</code>, <code>list_standups</code>, <code>get_standup</code>, <code>get_my_standups</code>, <code>list_runs</code>, <code>get_run</code>, <code>list_blockers</code>, <code>get_team</code>, <code>get_insights</code>, <code>get_schedule</code>, <code>list_time_off_requests</code>, <code>list_question_polls</code>, <code>get_question_poll_results</code> (results only where the owner may see them)</td></tr><tr><td><code>blockers:write</code></td><td><code>acknowledge_blocker</code>, <code>update_blocker</code>, <code>resolve_blocker</code></td></tr><tr><td><code>submit</code></td><td><code>submit_answers</code> (every answer required, and the mood when the standup asks for one; <code>moodComment</code> is optional), <code>skip_today</code> (takes a one-line <code>reason</code>, posted in the day&#39;s thread)</td></tr><tr><td><code>schedule</code></td><td><code>update_my_settings</code> (timezone, vacation), <code>set_working_days</code> (with <code>standupId</code>), <code>set_days_off</code>, <code>cancel_day_off</code>, <code>decide_time_off_request</code></td></tr><tr><td><code>manage</code></td><td><code>run_standup_now</code>, <code>nudge_standup</code> — only on standups you manage</td></tr></tbody></table><p>The token is shown once. Copy it before closing the panel.</p><h2 id="_3-connect-claude-code" tabindex="-1">3. Connect Claude Code <a class="header-anchor" href="#_3-connect-claude-code" aria-label="Permalink to &quot;3. Connect Claude Code&quot;">​</a></h2><p>For yourself, in every project:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --transport</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --scope</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> asyncup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://asyncup.example.com/mcp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --header</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer amcp_…&quot;</span></span></code></pre></div><p>For a team repo, commit a <code>.mcp.json</code> that keeps the token out of the file, and have each person export their own:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;asyncup&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://asyncup.example.com/mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;headers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Authorization&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bearer \${ASYNCUP_TOKEN}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ASYNCUP_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">amcp_…</span></span></code></pre></div><p>The <strong>Connect a client</strong> panel on the MCP settings page fills in your server&#39;s URL and, right after you create a token, the token itself.</p><p>Check it with <code>claude mcp list</code>, or <code>/mcp</code> inside a session. Then ask:</p><ul><li>&quot;Who on Platform hasn&#39;t posted today? Nudge them.&quot;</li><li>&quot;Summarise this week&#39;s blockers across my standups.&quot;</li><li>&quot;Answer today&#39;s standup: yesterday I shipped the export fix, today I&#39;m on the billing webhooks, no blockers.&quot;</li><li>&quot;Mark me off Friday, comp off for the weekend release.&quot;</li></ul><h2 id="how-the-tools-behave" tabindex="-1">How the tools behave <a class="header-anchor" href="#how-the-tools-behave" aria-label="Permalink to &quot;How the tools behave&quot;">​</a></h2><p>Every tool has a title, the four MCP hints and an output schema, so Claude Code can tell reads from writes and ask before anything that changes state. Read tools are read-only and never contact anyone. Every write may message people in Google Chat, so writes are marked as open-world.</p><p>Results come back as structured JSON in the same shapes as the <a href="./api.html">JSON API</a>, described by its OpenAPI document. A refusal (no such standup, not your blocker, the time-off policy says no) is an error result with a plain sentence the model can act on, not a protocol failure.</p><p>Tools see exactly what the token&#39;s owner sees, with the owner&#39;s current <a href="./roles.html">roles</a>: a member sees their own standups, a manager the standups they run, an admin everything. A token is only offered the tools its owner&#39;s permissions could use somewhere. A Viewer&#39;s token has no <code>run_standup_now</code> tool, for example. Each call is checked again for the standup it names. Anonymous moods stay anonymous, and <code>get_run</code> includes mood comments only when the owner may read them.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><ul><li>Tokens are stored hashed, expire 90 days after their last use, and can be revoked from the settings page at any time.</li><li>Requests that carry an <code>Origin</code> header are refused with <code>403</code>. MCP clients never send one, so a web page cannot reach the endpoint through a visitor&#39;s browser.</li><li><code>/mcp</code> shares the 60 requests a minute per IP limit with the other credential endpoints.</li><li>Every call is logged with the token, the tool, a short summary of the arguments and whether it worked, under <strong>Recent activity</strong>.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Answer</th><th>Meaning</th></tr></thead><tbody><tr><td><code>503 mcp_disabled</code></td><td>The server is switched off — see step 1</td></tr><tr><td><code>401</code></td><td>The token is missing, unknown, revoked or expired; the message says which</td></tr><tr><td><code>403</code></td><td>The request carried an <code>Origin</code> header — it came from a browser, not an MCP client</td></tr><tr><td>A tool is missing</td><td>The token lacks its scope, or (for <code>submit_answers</code> and <code>skip_today</code>) the server runs without the standup service</td></tr></tbody></table>`,28)])])}const u=s(i,[["render",n]]);export{k as __pageData,u as default};
